const getCharacterArray = (str) => Array.from(str);

const reverseArrayElements = (arr) => arr.reverse();

const joinArrayIntoString = (arr) => arr.join('');

const isInputValidString = (input) => typeof input === 'string';

const handleEmptyString = (str) => (str === '' ? '' : null);

const ensureStringInput = (input) => {
  if (!isInputValidString(input)) {
    throw new Error('Input must be a string.');
  }
  return input;
};

const reverseString = (str) => {
  const validatedString = ensureStringInput(str);
  const emptyStringResult = handleEmptyString(validatedString);
  if (emptyStringResult !== null) return emptyStringResult;

  const characters = getCharacterArray(validatedString);
  const reversedCharacters = reverseArrayElements(characters);
  return joinArrayIntoString(reversedCharacters);
};

