const isNonNegative = num => num >= 0;
const convertToInteger = num => Math.floor(num);
const initializeResult = () => 1;
const multiplyNumbers = (a, b) => a * b;
const decrementNumber = num => num - 1;
const isGreaterThanZero = num => num > 0;

const calculateFactorial = n => {
  const sanitizedN = convertToInteger(n);
  if (!isNonNegative(sanitizedN)) {
    throw new Error("Input must be a non-negative integer.");
  }

  let result = initializeResult();
  let currentNum = sanitizedN;

  while (isGreaterThanZero(currentNum)) {
    result = multiplyNumbers(result, currentNum);
    currentNum = decrementNumber(currentNum);
  }

  return result;
};

