const initializeSequence = (n) => {
  if (n <= 0) return [];
  return [0];
};

const appendNextNumber = (sequence) => {
  const lastIndex = sequence.length - 1;
  const secondLastIndex = sequence.length - 2;
  const nextValue = sequence[lastIndex] + sequence[secondLastIndex];
  sequence.push(nextValue);
};

const handleSingleElementCase = (sequence, n) => {
  if (n === 1) return sequence;
  sequence.push(1);
  return sequence;
};

const ensureMinimumLength = (n) => {
  if (n < 0) return 0;
  return n;
};

const calculateRemainingIterations = (n, currentLength) => {
  return n - currentLength;
};

const iterateAndAppend = (sequence, iterations) => {
  for (let i = 0; i < iterations; i++) {
    appendNextNumber(sequence);
  }
  return sequence;
};

const generateFibonacci = (n) => {
  const validatedN = ensureMinimumLength(n);
  let fibSequence = initializeSequence(validatedN);

  if (validatedN <= 1) {
    return handleSingleElementCase(fibSequence, validatedN);
  }

  handleSingleElementCase(fibSequence, 2); // Handles n=2 case: [0, 1]

  const remainingIterations = calculateRemainingIterations(validatedN, fibSequence.length);
  return iterateAndAppend(fibSequence, remainingIterations);
};

