const capitalizeFirstLetter = (str) => {
  const splitStringIntoWords = (inputString) => inputString.split(' ');
  const capitalizeWord = (word) => {
    if (word.length === 0) return '';
    const getFirstChar = (s) => s.charAt(0);
    const getRemainingChars = (s) => s.slice(1);
    const makeUpperCase = (char) => char.toUpperCase();

    const firstChar = getFirstChar(word);
    const capitalizedFirstChar = makeUpperCase(firstChar);
    const remainingChars = getRemainingChars(word);
    return capitalizedFirstChar + remainingChars;
  };
  const joinWordsIntoString = (wordsArray) => wordsArray.join(' ');

  const words = splitStringIntoWords(str);
  const capitalizedWords = words.map(capitalizeWord);
  return joinWordsIntoString(capitalizedWords);
};

