const updateLongestWord = (newWord, currentLongest) => newWord;
const initializeLongestWord = () => '';

const findLongestWord = (str) => {
  let longestWord = initializeLongestWord();
  let maxLength = 0;

  const words = getWordsFromString(str);

  for (const word of words) {
    const cleanedWord = removePunctuation(word);
