const getObjectKeys = obj => Object.keys(obj);
const getObjectValue = (obj, key) => obj[key];
const createNewObject = () => ({});
const setKeyValue = (obj, key, value) => { obj[key] = value; };
const isObjectEmpty = obj => getObjectKeys(obj).length === 0;
const iterateOverKeys = (obj, callback) => getObjectKeys(obj).forEach(callback);

const swapKeysAndValues = obj => {
  if (isObjectEmpty(obj)) {
    return createNewObject();
  }

  const swapped = createNewObject();
  iterateOverKeys(obj, key => {
    const value = getObjectValue(obj, key);
    setKeyValue(swapped, value, key);
  });
  return swapped;
};

