const decodeUriComponent = (str) => decodeURIComponent(str.replace(/\+/g, ' '));
const splitIntoPairs = (params) => params.split('&');
const splitPair = (pair) => pair.split('=');
const addKeyValuePair = (obj, key, value) => { obj[key] = value; return obj; };
const isNotEmptyString = (str) => str !== '';

const parseUrlParams = (url) => {
  const queryString = extractQueryParams(url);
  if (!isNotEmptyString(queryString)) {
