const GetMsPerDay = () => 1000 * 60 * 60 * 24;
const GetTimeInMs = (dateObj) => dateObj.getTime();
const CalculateTimeDifference = (ms1, ms2) => Math.abs(ms1 - ms2);
const ConvertMsToDays = (msDiff, msPerDay) => Math.floor(msDiff / msPerDay);
const EnsurePositiveResult = (value) => Math.abs(value);

const DaysBetweenDates = (date1Str, date2Str) => {
  const date1Obj = ParseDateString(date1Str);
  const date2Obj = ParseDateString(date2Str);

  const time1Ms = GetTimeInMs(date1Obj);
  const time2Ms = GetTimeInMs(date2Obj);

  const timeDifferenceMs = CalculateTimeDifference(time1Ms, time2Ms);
  const millisecondsPerDay = GetMsPerDay();

  const daysDifference = ConvertMsToDays(timeDifferenceMs, millisecondsPerDay);
  return EnsurePositiveResult(daysDifference);
};

