const convertToLowerCase = (str) => str.toLowerCase();
const trimWhitespace = (str) => str.trim();
const checkIsEmpty = (str) => str === '';

const normalizeString = (str) => trimWhitespace(convertToLowerCase(str));

const stringIncludes = (mainStr, subStr) => mainStr.includes(subStr);

const searchText = (text, keyword) => {
  if (checkIsEmpty(text) || checkIsEmpty(keyword)) {
    return false;
  }

  const normalizedText = normalizeString(text);
  const normalizedKeyword = normalizeString(keyword);

  const performInclusionCheck = (main, sub) => stringIncludes(main, sub);

  return performInclusionCheck(normalizedText, normalizedKeyword);
};

