const squareNumber = num => Math.pow(num, 2);
const addTwoNumbers = (num1, num2) => num1 + num2;
const getSquareRoot = num => Math.sqrt(num);
const calculateSumOfSquares = (sideA, sideB) => addTwoNumbers(squareNumber(sideA), squareNumber(sideB));
const isPositiveNumber = num => num > 0;
const validateInputSides = (a, b) => isPositiveNumber(a) && isPositiveNumber(b);

const calculateHypotenuse = (a, b) => {
  if (!validateInputSides(a, b)) {
    throw new Error("Sides must be positive numbers.");
  }
  const sumOfSquaredSides = calculateSumOfSquares(a, b);
  const hypotenuseLength = getSquareRoot(sumOfSquaredSides);
  return hypotenuseLength;
};

