const getCharCount = (str, index) => {
  let count = 0;
  const char = str[index];
  while (index < str.length && str[index] === char) {
    count++;
    index++;
  }
  return count;
};

const appendCharAndCount = (result, char, count) => result + char + count;

const buildCompressedString = (str) => {
  let compressed = '';
  let i = 0;
  while (i < str.length) {
    const char = str[i];
    const count = getCharCount(str, i);
    compressed = appendCharAndCount(compressed, char, count);
    i = advanceIndexByCount(i, count);
  }
  return compressed;
};

const isCompressedSmaller = (original, compressed) => compressed.length < original.length;

const advanceIndexByCount = (index, count) => index + count;

const getOriginalString = (str) => str;

const compressString = (str) => {
  if (str.length === 0) return getOriginalString(str);

  const compressed = buildCompressedString(str);

  if (isCompressedSmaller(str, compressed)) {
    return compressed;
  } else {
    return getOriginalString(str);
  }
};

