const formatCurrency = (amount, currencySymbol) => {
  const ensureNumber = (value) => parseFloat(value);
  const roundToTwoDecimals = (num) => Math.round(num * 100) / 100;
  const padWithZero = (num) => num < 10 ? '0' + num : num.toString();
  const formatNumberWithCommas = (num) => num.toLocaleString('en-US');
  const getDecimalPart = (num) => {
    const decimal = num % 1;
    return padWithZero(roundToTwoDecimals(decimal) * 100);
  };
  const getIntegerPart = (num) => Math.floor(num);

  const numericAmount = ensureNumber(amount);
  const roundedAmount = roundToTwoDecimals(numericAmount);
  const integerPart = getIntegerPart(roundedAmount);
  const formattedInteger = formatNumberWithCommas(integerPart);
  const decimalPart = getDecimalPart(roundedAmount);

  return `${currencySymbol}${formattedInteger}.${decimalPart}`;
};

