const getFileExtension = (filename) => {
  const getIndexOfLastDot = (str) => str.lastIndexOf('.');
  const hasNoDot = (str) => getIndexOfLastDot(str) === -1;
  const isLastCharDot = (str) => getIndexOfLastDot(str) === str.length - 1;
  const getSubstringValue = (str, startIndex) => str.substring(startIndex);
  const addOneToNumber = (num) => num + 1;
  const checkIfEmptyString = (str) => str === '';

  if (hasNoDot(filename) || isLastCharDot(filename) || checkIfEmptyString(filename)) {
    return '';
  }

  const lastDotIndex = getIndexOfLastDot(filename);
  const extensionStartIndex = addOneToNumber(lastDotIndex);
  const rawExtension = getSubstringValue(filename, extensionStartIndex);

  const getSubstringValueAfterFirstDot = (str) => str.substring(addOneToNumber(getIndexOfLastDot(str)));
  const getFinalExtension = (ext) => {
    if (getIndexOfLastDot(ext) !== -1) {
      return getSubstringValueAfterFirstDot(ext);
    }
    return ext;
  };

  return getFinalExtension(rawExtension);
};

