const ValidatePositiveNumber = (num) => num > 0;
const MultiplyNumbers = (a, b) => a * b;
const DivideNumbers = (a, b) => a / b;
const RoundToTwoDecimalPlaces = (num) => Math.round(num * 100) / 100;
const CalculateHeightSquared = (height) => MultiplyNumbers(height, height);
const PerformBMIDivision = (weight, heightSquared) => DivideNumbers(weight, heightSquared);

const CalculateBMI = (weightKg, heightM) => {
  if (!ValidatePositiveNumber(weightKg) || !ValidatePositiveNumber(heightM)) {
    throw new Error("Weight and height must be positive numbers.");
  }

  const heightSquared = CalculateHeightSquared(heightM);
  const rawBMI = PerformBMIDivision(weightKg, heightSquared);
  return RoundToTwoDecimalPlaces(rawBMI);
};
